use std::{collections::BTreeMap, fmt::Write as _};

use anyhow::{Result, anyhow, ensure};

use crate::group::{Action, ActionType, Member, Outcome, TAMPER_HELPER};

/// Reproduce the recorded group operations using only public libsignal APIs.
pub(crate) fn generate(name: &str, actions: &[Action]) -> Result<String> {
    ensure!(crate::valid_name(name), "テスト名が正しくありません");
    let mut source = String::from(
        "// generated by the viz tool (Sender Keys)\nmod support;\nuse futures_util::FutureExt;\nuse libsignal_protocol::*;\nuse rand::{TryRngCore as _, rngs::OsRng};\nuse support::*;\nuse uuid::Uuid;\n",
    );
    if actions.iter().any(|a| a.action_type == ActionType::Tamper) {
        source.push_str(TAMPER_HELPER);
    }
    writeln!(
        source,
        "#[test]\nfn viz_{name}() -> Result<(), SignalProtocolError> {{\n    async {{\n        let mut rng = OsRng.unwrap_err();\n        let distribution_id = Uuid::from_u128(1);"
    )?;
    for who in [Member::Alice, Member::Bob, Member::Carol, Member::Dave] {
        let who = who.name();
        writeln!(
            source,
            "        let mut {who}_store = test_in_memory_protocol_store()?;\n        let {who}_addr = ProtocolAddress::new({who:?}.into(), DeviceId::new(1).unwrap());"
        )?;
    }
    let mut messages = BTreeMap::new();
    for action in actions {
        let who = action.who.name();
        match action.action_type {
            ActionType::Join => {
                writeln!(
                    source,
                    "        // {who} joins the membership; no libsignal state changes."
                )?;
            }
            ActionType::Send => {
                let id = action
                    .message_id
                    .ok_or_else(|| anyhow!("送信に番号がありません"))?;
                let text = action
                    .text
                    .as_ref()
                    .ok_or_else(|| anyhow!("送信に本文がありません"))?;
                ensure!(
                    messages.insert(id, (action.who, text)).is_none(),
                    "送信番号が重複しています"
                );
                writeln!(
                    source,
                    "        let distribution_{id} = create_sender_key_distribution_message(&{who}_addr, distribution_id, &mut {who}_store, &mut rng).await?;"
                )?;
                for to in action
                    .distributed_to
                    .as_ref()
                    .ok_or_else(|| anyhow!("配布先がありません"))?
                {
                    writeln!(
                        source,
                        "        process_sender_key_distribution_message(&{who}_addr, &distribution_{id}, &mut {}_store).await?;",
                        to.name()
                    )?;
                }
                writeln!(
                    source,
                    "        let m{id} = group_encrypt(&mut {who}_store, &{who}_addr, distribution_id, {text:?}.as_bytes(), &mut rng).await?;"
                )?;
            }
            ActionType::Deliver | ActionType::Tamper | ActionType::Replay => {
                let id = action
                    .message_id
                    .ok_or_else(|| anyhow!("配達に番号がありません"))?;
                let (sender, text) = messages
                    .get(&id)
                    .ok_or_else(|| anyhow!("メッセージ #{id} の送信がありません"))?;
                let sender = sender.name();
                let i = action.i;
                if action.action_type == ActionType::Tamper {
                    writeln!(
                        source,
                        "        let mut bytes_{i} = m{id}.serialized().to_vec();\n        tamper_bytes(&mut bytes_{i});"
                    )?;
                } else {
                    writeln!(source, "        let bytes_{i} = m{id}.serialized();")?;
                }
                writeln!(
                    source,
                    "        let result_{i} = group_decrypt(&bytes_{i}, &mut {who}_store, &{sender}_addr).await;"
                )?;
                match action.expect {
                    Outcome::Ok => writeln!(
                        source,
                        "        assert_eq!(result_{i}?, {text:?}.as_bytes());"
                    )?,
                    Outcome::Duplicate => writeln!(
                        source,
                        "        assert!(matches!(result_{i}, Err(SignalProtocolError::DuplicatedMessage(..))));"
                    )?,
                    Outcome::BadSignature => writeln!(
                        source,
                        "        assert!(matches!(result_{i}, Err(SignalProtocolError::SignatureValidationFailed)));"
                    )?,
                    Outcome::NoSenderKey => writeln!(
                        source,
                        "        assert!(matches!(result_{i}, Err(SignalProtocolError::NoSenderKeyState {{ .. }})));"
                    )?,
                    Outcome::Error | Outcome::AnyError => {
                        writeln!(source, "        assert!(result_{i}.is_err());")?
                    }
                }
            }
        }
    }
    source.push_str("        Ok(())\n    }.now_or_never().expect(\"sync\")\n}\n");
    Ok(source)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::group::Sim;

    fn scenario() -> Result<Sim> {
        let mut s = Sim::new()?;
        s.send(Member::Alice, "今\"\\\n".into(), true)?;
        s.join(Member::Carol)?;
        s.receive(1, Member::Carol, ActionType::Deliver)?;
        s.send(Member::Alice, "new".into(), true)?;
        s.receive(1, Member::Carol, ActionType::Deliver)?;
        s.join(Member::Dave)?;
        s.send(Member::Bob, "first".into(), false)?;
        s.send(Member::Bob, "second".into(), false)?;
        s.receive(4, Member::Alice, ActionType::Tamper)?;
        s.receive(4, Member::Alice, ActionType::Deliver)?;
        s.receive(3, Member::Alice, ActionType::Deliver)?;
        s.receive(4, Member::Alice, ActionType::Replay)?;
        Ok(s)
    }

    #[test]
    fn escapes_and_emits_all_expectations() -> Result<()> {
        let mut s = scenario()?;
        let source = generate("group_escaped", &s.script)?;
        assert!(source.contains("\"今\\\"\\\\\\n\""));
        for error in [
            "DuplicatedMessage",
            "SignatureValidationFailed",
            "NoSenderKeyState",
        ] {
            assert!(source.contains(error));
        }
        assert!(!source.contains("viz_trace"));
        assert!(generate("../escape", &s.script).is_err());
        for expect in [Outcome::Error, Outcome::AnyError] {
            s.script.last_mut().unwrap().expect = expect;
            assert!(generate("group_escaped", &s.script)?.contains(".is_err()"));
        }
        Ok(())
    }

    #[test]
    #[ignore = "runs Cargo against a generated protocol integration test"]
    fn generated_group_script_runs() -> Result<()> {
        let name = "group_testgen_e2e";
        let path = crate::repo_root().join(format!("rust/protocol/tests/viz_{name}.rs"));
        ensure!(!path.exists(), "refusing to overwrite {}", path.display());
        std::fs::write(&path, generate(name, &scenario()?.script)?)?;
        let result = std::process::Command::new("cargo")
            .args([
                "test",
                "-p",
                "libsignal-protocol",
                "--test",
                &format!("viz_{name}"),
            ])
            .current_dir(crate::repo_root())
            .output();
        std::fs::remove_file(&path)?;
        let output = result?;
        assert!(
            output.status.success(),
            "{}\n{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        Ok(())
    }
}
